// Arma el aviso de un flujo que falló. Lee lo que n8n manda al disparador de errores.
const e = $json.execution || {};
const w = $json.workflow || {};
const nodo = e.lastNodeExecuted || 'un nodo que no se pudo identificar';
const mensaje = (e.error && e.error.message) || 'sin detalle';
const html = `<p>El flujo <b>${w.name || '(sin nombre)'}</b> falló en el nodo <b>${nodo}</b>.</p>
<p><b>Qué dijo n8n:</b> ${mensaje}</p>
<p>${e.url ? `Ver la ejecución: <a href="${e.url}">${e.url}</a>` : 'n8n no mandó el enlace de la ejecución.'}</p>
<p style="color:#6b7280">Mientras no se corrija, el reporte o la carga de esa vez no se hizo. Se puede correr a mano desde n8n con "Correr a mano".</p>`;
return [{ json: { asunto: `Falló un flujo del CRM: ${w.name || ''}`, html } }];
